cards.sql:
SELECT 사원번호, 이름, 부서번호
FROM 사원
WHERE 부서번호 = 10;

SELECT 부서번호, 부서명
FROM 부서;

SELECT 사원번호, 이름, 부서번호
FROM 사원
WHERE 부서번호 = 20;

UPDATE 사원
SET 급여 = 급여 + 100
WHERE 사원번호 = 1011;

SELECT 이름, 급여
FROM 사원
WHERE 사원번호 = 1011;

SELECT 이름, 직급
FROM 사원
WHERE 부서번호 = 10;

SELECT 이름, 직급, 급여
FROM 사원
ORDER BY 급여 DESC;

SELECT 이름, 커미션
FROM 사원
ORDER BY 커미션;

SELECT 이름, 커미션
FROM 사원
ORDER BY 커미션 NULLS LAST;

SELECT 사원.이름, 사원.부서번호, 부서.부서명
FROM 사원, 부서
WHERE 사원.부서번호 = 부서.부서번호;

SELECT COUNT(*) AS 조건없음
FROM 사원, 부서;

SELECT COUNT(*) AS 조건있음
FROM 사원 e, 부서 d
WHERE e.부서번호 = d.부서번호;

SELECT e.이름, d.부서명
FROM 사원 e, 부서 d
WHERE e.사원번호 = 1001;

SELECT e.이름, d.부서명
FROM 사원 e, 부서 d
WHERE e.부서번호 = d.부서번호;

SELECT 이름 AS 짝이없어빠진사원
FROM 사원
WHERE 부서번호 IS NULL;

SELECT 부서번호, e.이름, d.부서명
FROM 사원 e JOIN 부서 d USING (부서번호)
WHERE 부서번호 = 30;

SELECT 부서번호, 이름, 부서명
FROM 사원 NATURAL JOIN 부서
WHERE 부서번호 = 10;

SELECT d.부서명, g.등급
FROM 부서 d CROSS JOIN 급여등급 g
ORDER BY d.부서번호, g.등급;

SELECT d.부서명 AS 사원있는부서
FROM 부서 d
WHERE EXISTS (SELECT 1 FROM 사원 e WHERE e.부서번호 = d.부서번호);

SELECT d.부서명 AS 사원없는부서
FROM 부서 d
WHERE NOT EXISTS (SELECT 1 FROM 사원 e WHERE e.부서번호 = d.부서번호);

SELECT COUNT(*) AS NOT_IN으로찾은부서수
FROM 부서
WHERE 부서번호 NOT IN (SELECT 부서번호 FROM 사원);

SELECT 이름, 직급 FROM 사원 WHERE 부서번호 = 20
UNION
SELECT 이름, 직급 FROM 사원 WHERE 직급 = '과장';

SELECT 이름, 직급 FROM 사원 WHERE 부서번호 = 20
UNION ALL
SELECT 이름, 직급 FROM 사원 WHERE 직급 = '과장';

SELECT 이름 FROM 사원 WHERE 부서번호 = 20
INTERSECT
SELECT 이름 FROM 사원 WHERE 직급 = '과장';

SELECT 부서번호 FROM 사원
INTERSECT
SELECT 부서번호 FROM 부서;

SELECT 직급 FROM 사원 WHERE 부서번호 = 20
INTERSECT
SELECT 직급 FROM 사원 WHERE 부서번호 = 30;

SELECT 이름 FROM 사원 WHERE 부서번호 = 20
EXCEPT
SELECT 이름 FROM 사원 WHERE 직급 = '과장';

SELECT 부서번호 FROM 부서
EXCEPT
SELECT 부서번호 FROM 사원;

SELECT 부서번호 FROM 사원
UNION
SELECT 부서번호 FROM 부서;

SELECT 부서번호 AS 부서테이블에없는값 FROM 사원
EXCEPT
SELECT 부서번호 FROM 부서;

SELECT 부서번호 AS 사원없는부서 FROM 부서
EXCEPT
SELECT 부서번호 FROM 사원;

-- 오라클 12c 이상: ... ORDER BY 급여 DESC OFFSET 3 ROWS FETCH NEXT 3 ROWS ONLY;
-- SQLite에서는 LIMIT와 OFFSET으로 쓴다.
SELECT 이름, 급여
FROM 사원
ORDER BY 급여 DESC
LIMIT 3 OFFSET 3;

SELECT 사원번호, 이름, 직급, 관리자번호
FROM 사원
ORDER BY 관리자번호, 사원번호;
